namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string? Name { get; set; }

    [Required(ErrorMessage = "Student ID is required.")]
    public string? StudentId { get; set; }

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Description = "Study of computation, algorithms, data structures, and the design of software and hardware systems." },
            new() { Id = 2, Name = "Mathematics", Description = "Exploration of abstract structures, quantity, change, and space through rigorous logical reasoning." },
            new() { Id = 3, Name = "Physics", Description = "Investigation of matter, energy, and the fundamental forces that govern the natural world." },
            new() { Id = 4, Name = "English", Description = "Analysis and creation of literary and expository texts, with emphasis on critical thinking and communication." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, DepartmentId = 1, Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published extensively on CS education.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques.", Credits = 4, Schedule = "TTh 10:30–11:50 AM", InstructorName = "Dr. James Wright", InstructorBio = "Dr. Wright specializes in algorithm optimization and competitive programming.", IsFeatured = false },
            new() { Id = 3, DepartmentId = 1, Title = "Database Systems", Description = "Principles of database design, SQL, normalization, and transaction management.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Garcia", InstructorBio = "Dr. Garcia worked as a database architect at Oracle before joining academia.", IsFeatured = false },
            new() { Id = 4, DepartmentId = 1, Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search, knowledge representation, machine learning, and neural networks.", Credits = 4, Schedule = "TTh 2:00–3:20 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published extensively on CS education.", IsFeatured = true },

            // Mathematics
            new() { Id = 5, DepartmentId = 2, Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible to all students.", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, and eigenvalues.", Credits = 3, Schedule = "TTh 9:00–10:20 AM", InstructorName = "Dr. Elena Petrov", InstructorBio = "Dr. Petrov's research focuses on numerical linear algebra and its applications in data science.", IsFeatured = false },
            new() { Id = 7, DepartmentId = 2, Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible to all students.", IsFeatured = false },

            // Physics
            new() { Id = 8, DepartmentId = 3, Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist who has worked at CERN and Fermilab.", IsFeatured = true },
            new() { Id = 9, DepartmentId = 3, Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "TTh 1:00–2:20 PM", InstructorName = "Dr. Lisa Nakamura", InstructorBio = "Dr. Nakamura researches novel electromagnetic materials and metamaterials.", IsFeatured = false },
            new() { Id = 10, DepartmentId = 3, Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist who has worked at CERN and Fermilab.", IsFeatured = false },

            // English
            new() { Id = 11, DepartmentId = 4, Title = "Composition and Rhetoric", Description = "Development of academic writing skills, argumentation, and rhetorical analysis.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Prof. Diana Wells", InstructorBio = "Prof. Wells is a published author and writing coach with expertise in academic and creative writing.", IsFeatured = false },
            new() { Id = 12, DepartmentId = 4, Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present.", Credits = 3, Schedule = "TTh 11:00 AM–12:20 PM", InstructorName = "Dr. Marcus Johnson", InstructorBio = "Dr. Johnson specializes in 20th-century American fiction and African American literary traditions.", IsFeatured = true },
            new() { Id = 13, DepartmentId = 4, Title = "Creative Writing", Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction.", Credits = 3, Schedule = "TTh 3:30–4:50 PM", InstructorName = "Prof. Diana Wells", InstructorBio = "Prof. Wells is a published author and writing coach with expertise in academic and creative writing.", IsFeatured = false },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public List<Course> GetCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

