@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<h1>Welcome to the University Course Catalog</h1>
<p class="lead">Browse our departments and courses to find the perfect fit for your academic journey.</p>

<h2 class="mt-4">Featured Courses</h2>
<div class="row">
    @foreach (var course in featuredCourses)
    {
        var dept = departments.FirstOrDefault(d => d.Id == course.DepartmentId);
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@course.Title</h5>
                    <p class="card-text">Credits: @course.Credits</p>
                    @if (dept is not null)
                    {
                        <a href="/departments/@dept.Id">@dept.Name</a>
                    }
                </div>
                <div class="card-footer">
                    <a href="/courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mt-4">Departments</h2>
<ul class="list-group">
    @foreach (var dept in departments)
    {
        <li class="list-group-item">
            <a href="/departments/@dept.Id">@dept.Name</a> &mdash; @dept.Description
        </li>
    }
</ul>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
}
else
{
    <PageTitle>@course.Title</PageTitle>

    <h1>@course.Title</h1>
    <p class="text-muted">
        Department: <a href="/departments/@course.DepartmentId">@departmentName</a>
    </p>

    <p>@course.Description</p>

    <table class="table table-bordered w-auto">
        <tr><th>Credits</th><td>@course.Credits</td></tr>
        <tr><th>Schedule</th><td>@course.Schedule</td></tr>
    </table>

    <h3 class="mt-4">Instructor</h3>
    <p><strong>@course.InstructorName</strong></p>
    <p>@course.InstructorBio</p>

    <a href="/enroll?courseId=@course.Id" class="btn btn-success">Enroll in this Course</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? course;
    private string departmentName = string.Empty;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
        if (course is not null)
        {
            var dept = Catalog.GetDepartments().FirstOrDefault(d => d.Id == course.DepartmentId);
            departmentName = dept?.Name ?? "Unknown";
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enroll</PageTitle>

<h1>Course Enrollment</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Confirmed!</h4>
        <p>Thank you, <strong>@Model.Name</strong>. You have been enrolled in <strong>@GetCourseName(Model.CourseId)</strong>.</p>
    </div>
    <a href="/courses" class="btn btn-primary">Back to Courses</a>
}
else
{
    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
        <AntiforgeryToken />
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="name" class="form-label">Name</label>
            <InputText id="name" class="form-control" @bind-Value="Model.Name" />
            <ValidationMessage For="() => Model.Name" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                <option value="0">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id">@course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    private int? CourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses(null, null);
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        submitted = true;
    }

    private string GetCourseName(int courseId)
    {
        return Catalog.GetCourse(courseId)?.Title ?? "Unknown Course";
    }
}

